// Renaming is a metadata change: preserve the sound identity/revision and any existing musical references.
  function rename(id, expectedRevision, label) {
    const name = typeof label === 'string' ? label.trim() : '';
    if (!name || name.length > 100) throw new Error('Instrumentname muss 1 bis 100 Zeichen enthalten.');
    const entries = list(), index = entries.findIndex(e => e.id === id);
    if (index < 0) throw new Error('Instrument wurde nicht gefunden.');
    if (entries[index].revision !== expectedRevision) throw new Error('Nodal revision conflict');
    const old = entries[index];
    if (old.instrument.name === name) return old;
    const updated = {id: old.id, revision: old.revision, instrument: model.normalize({...old.instrument, name})};
    entries[index] = updated;
    write(entries);
    return updated;
  }

