LibraryEntryLabel(entry, entries) {
  const name = entry.instrument.name;
  const same = entries.filter(e => e.instrument.name === name);
  const index = same.findIndex(e => e.id === entry.id) + 1;
  return name + ' · ' + entry.instrument.nodes.length + ' Knoten' + (same.length > 1 ? ' · ' + index + '/' + same.length : '');
}
function nodalInstrumentMenu(composer) {
  // Library sound sources and currently referenced project snapshots are different entities.
  // Deleting a library entry must never silence an existing composition.
  const choices = new Map(), entries = (() => { try { return __XenNodalLibrary.list(); } catch { return []; } })();
  const referenced = new Set();
  for (const track of composer?.tracks ?? []) {
    if (track.instrumentPreset?.startsWith('nodal:')) referenced.add(track.instrumentPreset);
    for (const note of composer?.notes ?? []) if (note.trackId === track.id) {
      const id = note.instrumentPresetOverride || track.instrumentPreset;
      if (id?.startsWith('nodal:')) referenced.add(id);
    }
  }
  for (const entry of entries) choices.set('nodal:' + entry.id + '@' + entry.revision, {instrument: entry.instrument, kind: 'library', entry});
  for (const [id, instrument] of Object.entries(composer?.nodalInstruments ?? {})) if (referenced.has(id)) {
    const stored = choices.get(id);
    // The project owns its snapshot; the library may only contribute a changed display name.
    choices.set(id, {...stored, instrument: stored?.instrument ?? instrument, kind: stored ? 'library' : 'project'});
  }
  if (!choices.size) return [];
  const values = Array.from(choices, ([id, data]) => ({id, ...data}));
  const counts = new Map();
  for (const value of values) counts.set(value.instrument.name, (counts.get(value.instrument.name) ?? 0) + 1);
  const seen = new Map();
  return [{id: 'nodal', label: 'Nodal · Synthetische Instrumente', options: values.map(value => {
    const {id, instrument, kind} = value;
    const index = (seen.get(instrument.name) ?? 0) + 1;
    seen.set(instrument.name, index);
    return {id, label: instrument.name + ' · ' + instrument.nodes.length + ' Knoten' +
      (counts.get(instrument.name) > 1 ? ' · ' + index + '/' + counts.get(instrument.name) : '') +
      (kind === 'project' ? ' · im Projekt' : ''), hint: 'Direkte Synthese', baseHz: instrument.referenceHz, originLabel: 'Nodal'};
  })}];
}
/* Compact library management is available where the musician actually chooses instruments.
   Edits change only library metadata, never note geometry, PCM or synthesizer revision. */
function NodalLibraryManager({composer, onMutateLoopComposer}) {
  const h = P.createElement;
  const [open, setOpen] = P.useState(false);
  const [entries, setEntries] = P.useState(() => { try { return __XenNodalLibrary.list(); } catch { return []; } });
  const [drafts, setDrafts] = P.useState({});
  const [message, setMessage] = P.useState('');
  function refresh() {
    const items = __XenNodalLibrary.list();
    setEntries(items);
    setDrafts(Object.fromEntries(items.map(e => [e.id, e.instrument.name])));
  }
  function notify() { window.dispatchEvent(new Event('xensonar:nodal-library-changed')); }
  function renameEntry(entry) {
    try {
      const oldName = entry.instrument.name;
      const next = __XenNodalLibrary.rename(entry.id, entry.revision, drafts[entry.id]);
      const preset = 'nodal:' + entry.id + '@' + entry.revision;
      if (composer?.nodalInstruments?.[preset] && oldName !== next.instrument.name) {
        onMutateLoopComposer(c => {
          if (c.nodalInstruments?.[preset]) c.nodalInstruments[preset] = {...c.nodalInstruments[preset], name: next.instrument.name};
          for (const track of c.tracks) if (track.instrumentPreset === preset && track.label === oldName) track.label = next.instrument.name;
        });
      }
      refresh(); notify(); setMessage('Umbenannt: ' + next.instrument.name + ' · Klang und Noten unverändert.');
    } catch (error) { setMessage('Umbenennen: ' + error.message); }
  }
  function removeEntry(entry) {
    if (!window.confirm('„' + entry.instrument.name + '“ aus der Nodal-Bibliothek entfernen? Bereits verwendete Noten und Projektkopien bleiben erhalten.')) return;
    try {
      __XenNodalLibrary.remove(entry.id, entry.revision);
      refresh(); notify(); setMessage('Aus der Bibliothek entfernt. Vorhandene Kompositionen bleiben erhalten.');
    } catch (error) { setMessage('Entfernen: ' + error.message); }
  }
  return h('section', {className: 'nd-library-manager', 'aria-label': 'Nodal-Instrumentenbibliothek'},
    h('button', {type: 'button', 'aria-expanded': open, onClick: () => {
      if (!open) try { refresh(); } catch (error) { setMessage(error.message); }
      setOpen(!open);
    }}, 'Nodal-Klänge verwalten (' + entries.length + ')' + (open ? ' ▴' : ' ▾')),
    open ? h('div', {className: 'nd-library-manager-content'},
      h('div', {className: 'nd-library-manager-help'}, 'Gespeicherte Nodal-Instrumente: Namen ändern oder Einträge entfernen. Senden aus Sounddesign legt auch einen Bibliothekseintrag an. Den Klang selbst bearbeitest du im Nodal-Sounddesign.'),
      entries.length ? entries.map(entry => h('div', {key: entry.id, className: 'nd-library-manager-row'},
        h('label', {className: 'nd-library-manager-name'},
          h('span', null, nodalLibraryEntryLabel(entry, entries)),
          h('input', {'aria-label': 'Name für ' + nodalLibraryEntryLabel(entry, entries), value: drafts[entry.id] ?? entry.instrument.name, maxLength: 100,
            onChange: e => setDrafts(v => ({...v, [entry.id]: e.target.value}))})),
        h('button', {type: 'button', disabled: (drafts[entry.id] ?? entry.instrument.name).trim() === entry.instrument.name,
          onClick: () => renameEntry(entry)}, 'Umbenennen'),
        h('button', {type: 'button', onClick: () => removeEntry(entry), 'aria-label': nodalLibraryEntryLabel(entry, entries) + ' entfernen'}, 'Entfernen')
      )) : h('div', {className: 'nd-library-manager-help'}, 'Noch keine Nodal-Klänge gespeichert.'),
      h('div', {className: 'nd-library-manager-help'}, 'Entfernte Instrumente bleiben in bestehenden Melodic-Kompositionen spielbar. Solche Kopien tragen „im Projekt“.'),
      message ? h('div', {className: 'nd-library-manager-message', role: 'status'}, message) : null
    ) : null)

